import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"33、【遁】 艮下乾上","description":"周易口訣義 - 33、【遁】 艮下乾上","frontmatter":{"title":"33、【遁】 艮下乾上","description":"周易口訣義 - 33、【遁】 艮下乾上"},"headers":[],"relativePath":"classics/koujueyi/035.md","filePath":"classics/koujueyi/035.md"}'),r={name:"classics/koujueyi/035.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_33、【遁】-艮下乾上" tabindex="-1">33、【遁】 艮下乾上 <a class="header-anchor" href="#_33、【遁】-艮下乾上" aria-label="Permalink to “33、【遁】 艮下乾上”">​</a></h1><p>彖曰：「遁亨」，遁而亨也。剛當位而應，與時行也。「小利貞」，浸而長也。遁之時義大矣哉！</p><p>象曰：天下有山，遁。君子以遠小人，不惡而嚴。</p><p>初六：遁尾，厲。勿用有攸往。</p><p>象曰：「遁尾」之厲，不往何災也。</p><p>六二：執之用黃牛之革，莫之勝說。</p><p>象曰：執用黃牛，固志也。</p><p>九三：系遁，有疾，厲。畜臣妾，吉。</p><p>象曰：「系遁」之厲，有疾憊也。「畜臣妾吉」，不可大事也。</p><p>九四，好遁，君子吉，小人否。</p><p>象曰：君子「好遁」，「小人否」也。</p><p>九五，嘉遁，貞吉。</p><p>象曰：「嘉遁貞吉」，以正志也。</p><p>上九，肥遁，無不利。</p><p>象曰：「肥遁無不利」，無所疑也。</p><p>解讀</p><p>「遁亨」者，遁是逃隱退避之名，諭小人道長，君子當退避而後可亨也。「小利貞」者，雖居小人道長之時，正道亦未全滅，亦可小利為正也。象曰「天下有山，遁」者，積陽為天，積陰為地，山者，陰長之象，山勢漸長以逼於天，天性高遠，逼而不至，如天漸高避于山。君子之遠小人不惡而嚴者，處小人道長之世，近之必致危害，故須遠避，不可與之為惡，又須莊敬嚴恭，自保其身也。</p><p>「初六，遁尾，厲，勿用有攸往」者，「尾」之為物，最在體後，處遁之時，眾皆逃遁，唯初六最在於後，即必被執獲，故致危厲。若能知尾為危，不如不往，即無災害，故曰「勿用有攸往」也。</p><p>「六二，執之用黃牛之革，莫之勝說」者，黃，中色也，以譬中和也；牛革，即是牛皮，喻其厚順也。處逃遁之時，眾皆逃遁，唯六二得位守中，不肯逃遁，意欲率眾以安其處。何以勸勉之？必須用中和之道，厚順之德。有此之善，人莫勝己，可脫免逃遁而去也。</p><p>「九三，系遁，有疾厲，畜臣妾吉」者，夫親暱小人，即為小人侵傷，故有疾憊危厲也。然親洽於二，雖得如似畜養臣妾，不可興建大事，故小象雲「不可大事也」。</p><p>「九四，好遁，君子吉，小人否」者，有應在內，即情有所戀；身處於外，即志欲遠遁。若知幾君子，思慮危害，而能超然不顧所應，而好遁避，即獲吉矣，故曰「好遁，君子吉」；小人處此，情有所戀，不肯遁，故曰「小人否」，「否」是否臧之「否」也。</p><p>「九五，嘉遁，貞吉」者，嘉，美也；五居尊位，為遁之主，率正小人之志，以安於俗，不令遁散，故獲美善之吉也。</p><p>上九，肥遁，無不利者。肥者，優饒之名。上九處遁之時，最居於外，內又無應，即無顧戀，超然高舉，不為小人所累，是逃遁之時而得優饒者也。既有如斯之德，即「無不利」矣。</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
